def _parse_version(version):
    """Parse a semantic version string into a precedence sort key.

    Build metadata is ignored, as required by SemVer 2.0.0.
    """
    without_build = version.split('+', 1)[0]

    if '-' in without_build:
        core, prerelease = without_build.split('-', 1)
        prerelease_ids = prerelease.split('.') if prerelease else []
    else:
        core, prerelease_ids = without_build, None

    parts = core.split('.')
    if len(parts) != 3:
        raise ValueError('invalid semantic version: %r' % version)

    major, minor, patch = (int(part) for part in parts)

    if prerelease_ids is None:
        # A normal release has higher precedence than any pre-release of the
        # same major/minor/patch version.
        prerelease_key = (1,)
    else:
        identifiers = []
        for identifier in prerelease_ids:
            if identifier.isdigit():
                identifiers.append((0, int(identifier)))
            else:
                identifiers.append((1, identifier))
        prerelease_key = (0, tuple(identifiers))

    return (major, minor, patch, prerelease_key)


def sort_versions(vs):
    """Return versions sorted by SemVer 2.0.0 precedence, lowest first.

    Sorting is stable, so versions with equal precedence retain their input
    order.
    """
    return sorted(vs, key=_parse_version)
